P2B-EVAL-CD02:
NUMBER x.
INPUT(x).
IF (x>=80) { DISPLAYNL("A"). } ELSEIF (x>=60) { DISPLAYNL("B"). } ELSE { DISPLAYNL("C"). }

P2B-EVAL-CD03:
NUMBER y.
INPUT(y).
IF ((y%4==0 AND y%100!=0) OR y%400==0) { DISPLAYNL("LEAP"). } ELSE { DISPLAYNL("COMMON"). }

P2B-EVAL-CD06:
IMPORT strings.
SENTENCE line.
INPUT(line).
SENTENCE[] parts = strings.SPLIT(line, "|").
NUMBER a = strings.TO_NUMBER(parts[0]).
NUMBER b = strings.TO_NUMBER(parts[1]).
NUMBER c = strings.TO_NUMBER(parts[2]).
NUMBER positives=0.
NUMBER negatives=0.
IF (a>0) { positives+=1. } ELSEIF (a<0) { negatives+=1. }
IF (b>0) { positives+=1. } ELSEIF (b<0) { negatives+=1. }
IF (c>0) { positives+=1. } ELSEIF (c<0) { negatives+=1. }
IF (positives>=2) { DISPLAYNL("POS"). } ELSEIF (negatives>=2) { DISPLAYNL("NEG"). } ELSE { DISPLAYNL("MIX"). }

P2B-EVAL-CD07:
NUMBER t.
INPUT(t).
IF (t<0) { DISPLAYNL("NEGATIVE"). } ELSEIF (t==0) { DISPLAYNL("ZERO"). } ELSEIF (t%2==0) { DISPLAYNL("POSITIVE_EVEN"). } ELSE { DISPLAYNL("POSITIVE_ODD"). }

P2B-EVAL-CD08:
NUMBER x.
INPUT(x).
IF (x==5 OR x==15) { DISPLAYNL("EDGE"). } ELSEIF (x>5 AND x<15) { DISPLAYNL("INSIDE"). } ELSE { DISPLAYNL("OUTSIDE"). }

P2B-EVAL-CD09:
NUMBER n.
INPUT(n).
IF (n%6==0) { DISPLAYNL("BOTH"). } ELSEIF (n%2==0) { DISPLAYNL("TWO"). } ELSEIF (n%3==0) { DISPLAYNL("THREE"). } ELSE { DISPLAYNL("NEITHER"). }

P2B-EVAL-CD11:
NUMBER w.
INPUT(w).
IF (w<=0) { DISPLAYNL("FREE"). } ELSEIF (w<=5) { DISPLAYNL("LIGHT"). } ELSEIF (w<=20) { DISPLAYNL("MEDIUM"). } ELSE { DISPLAYNL("HEAVY"). }

P2B-EVAL-CD12:
NUMBER n.
INPUT(n).
IF (n>=10 AND n<=30 AND n%2!=0) { DISPLAYNL("YES"). } ELSE { DISPLAYNL("NO"). }

P2B-EVAL-CD15:
NUMBER n.
INPUT(n).
IF (n>=1 AND n<=100 AND n%7==0) { DISPLAYNL("ACCEPT"). } ELSE { DISPLAYNL("REJECT"). }

P2B-EVAL-CP01:
NUMBER n.
INPUT(n).
NUMBER total=0. LOOP (NUMBER i=1 TILL i<n, i++) { IF (n%i==0) { total+=i. } } IF (total==n) { DISPLAYNL("PERFECT"). } ELSE { DISPLAYNL("OTHER"). }

P2B-EVAL-CP02:
NUMBER n.
INPUT(n).
NUMBER count=0. LOOP (NUMBER i=1 TILL i<=n, i++) { IF (n%i==0) { count+=1. } } IF (count==2) { DISPLAYNL("PRIME"). } ELSE { DISPLAYNL("OTHER"). }

P2B-EVAL-CP03:
NUMBER n.
INPUT(n).
NUMBER total=0. LOOP (NUMBER i=1 TILL i<=n, i++) { total+=i*i. } IF (total%2==0) { DISPLAYNL("EVEN"). } ELSE { DISPLAYNL("ODD"). }

P2B-EVAL-CP05:
NUMBER n.
INPUT(n).
NUMBER count=0. LOOP (NUMBER i=1 TILL i<=n, i++) { IF (n%i==0) { count+=1. } } IF (count%2==0) { DISPLAYNL("EVENCOUNT"). } ELSE { DISPLAYNL("ODDCOUNT"). }

P2B-EVAL-CP06:
NUMBER n.
INPUT(n).
NUMBER total=n*(n+1)/2. IF (total>20) { DISPLAYNL("OVER"). } ELSE { DISPLAYNL("UNDER"). }

P2B-EVAL-CP09:
NUMBER n.
INPUT(n).
NUMBER product=1. LOOP (NUMBER i=1 TILL i<=n, i++) { IF (i%2==0) { product*=i. } } IF (product>=1000) { DISPLAYNL("LARGE"). } ELSE { DISPLAYNL("SMALL"). }

P2B-EVAL-CP10:
NUMBER n.
INPUT(n).
FUNCTION term(NUMBER x) { RETURN x*x+1. } RETURNS NUMBER. NUMBER total=0. LOOP (NUMBER i=1 TILL i<=n, i++) { total+=term(i). } IF (total%3==0) { DISPLAYNL("THREE"). } ELSE { DISPLAYNL("OTHER"). }

P2B-EVAL-CP11:
NUMBER n.
INPUT(n).
NUMBER total=0. LOOP (NUMBER i=1 TILL i<=n, i++) { total+=i*(i+2). } IF (total%2==0) { DISPLAYNL("EVEN"). } ELSE { DISPLAYNL("ODD"). }

P2B-EVAL-CP12:
NUMBER n.
INPUT(n).
NUMBER total=0. LOOP (NUMBER i=1 TILL i<=n, i++) { IF (i%2==0) { total-=i. } ELSE { total+=i. } } IF (total>=0) { DISPLAYNL("NONNEG"). } ELSE { DISPLAYNL("NEG"). }
